def mean_absolute_deviation(numbers: List[float]) -> float:
    if len(numbers) == 0:
        return 0
    total = 0.0
    for i in range(len(numbers)):
        total = total + numbers[i]
    mean = total / len(numbers)
    answer = 0
    for i in range(len(numbers)):
        answer = answer + abs(numbers[i] - mean)
    return answer / len(numbers)


