def mean_of_squares(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate the mean of the squared
    values.
    The mean of a set of values is the total of the values divided by the
    number of values, or: mean = total_value / number_of_values.
    >>> mean_of_squares([1, 4, 3, 7, 9])
    6.4
    """
    total_sum = 0.0
    for number in numbers:
        total_sum += number ** 2
    return total_sum / len(numbers)


