    """ Compute the standard deviation of a dataset """
    mean_val = mean(numbers)
    return sum([abs(x - mean_val) for x in numbers]) / len(numbers)


def zscore(numbers: List[float]) -> List[float]:
    """ Convert a dataset to z-scores.  Z-score data is useful for data
    analysis purposes because it removes the effect of outliers by
    adjusting data so that it is mean=0 and std=1.
    >>> zscore([10,11,12])
    [-1.632993161855452, -1.118033988749895, 0.0]
    """
    return [(x - mean(numbers)) / stdev(numbers) for x in numbers]


